import SwiftUI
import AppKit

/// Provider logos with embedded Base64 PNG data (48x48 square).
/// This avoids SPM Bundle.module issues with executable targets.
enum ProviderLogos {
    // MARK: - Embedded Logo Data (48x48 square PNGs)

    /// Anthropic logo - coral "A" letterform
    private static let anthropicBase64 = ""

    /// OpenAI logo - black hexagon
    private static let openaiBase64 = ""

    /// Blaze app logo - flame icon
    private static let blazeBase64 = ""

    /// Google/Gemini logo - four color sparkle
    private static let googleBase64 = ""

    // MARK: - Image Loading

    private static func loadImage(from base64: String) -> NSImage? {
        guard let data = Data(base64Encoded: base64) else { return nil }
        return NSImage(data: data)
    }

    private static func nsImage(for provider: AIProvider) -> NSImage? {
        switch provider {
        case .anthropic:
            return loadImage(from: anthropicBase64)
        case .openai:
            return loadImage(from: openaiBase64)
        case .google:
            return loadImage(from: googleBase64)
        case .community:
            return nil
        }
    }

    // MARK: - SwiftUI Image Accessor

    static func image(for provider: AIProvider, size: CGFloat = 20) -> some View {
        Group {
            if let nsImage = nsImage(for: provider) {
                Image(nsImage: nsImage)
                    .resizable()
                    .interpolation(.high)
                    .aspectRatio(contentMode: .fit)
            } else {
                // Fallback to SF Symbol for community/unknown providers
                Image(systemName: provider.fallbackSymbol)
                    .font(.system(size: size * 0.8))
                    .foregroundStyle(provider.brandColor)
            }
        }
        .frame(width: size, height: size)
    }

    // MARK: - Blaze App Logo

    /// Returns the Blaze app logo at the specified size.
    /// Uses embedded Base64 PNG to avoid SPM Bundle.module issues.
    static func blazeLogo(size: CGFloat = 48) -> some View {
        Group {
            if let nsImage = loadImage(from: blazeBase64) {
                Image(nsImage: nsImage)
                    .resizable()
                    .interpolation(.high)
                    .aspectRatio(contentMode: .fit)
            } else {
                // Fallback to SF Symbol
                Image(systemName: "flame.fill")
                    .font(.system(size: size * 0.8))
                    .foregroundStyle(.orange)
            }
        }
        .frame(width: size, height: size)
    }
}
